/* @autogenerated */
package net.civeira.phylax.features.oauth.userinvitation.application.usecase.accept;

import java.time.Instant;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.features.access.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.features.oauth.userinvitation.domain.InvitationRecord;
import net.civeira.phylax.features.oauth.userinvitation.domain.UserInvitationSession;
import net.civeira.phylax.features.oauth.userinvitation.domain.gateway.InvitationAcceptGateway;
import net.civeira.phylax.features.oauth.userinvitation.domain.gateway.UserInvitationLookupGateway;
import net.civeira.phylax.features.oauth.userinvitation.domain.gateway.UserInvitationSessionGateway;

/**
 * Accepts an invitation from its link (task 2.2): the token must name a pending, unexpired
 * invitation of the tenant, and the account is created only once even with concurrent requests.
 * Every refusal has the same message, so a link cannot be probed.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class InvitationAcceptUsecase {

  /**
   * Minimum length of the password of an invited account.
   */
  public static final int MIN_PASSWORD = 8;
  private static final String INVALID = "This invitation is invalid or has expired.";

  private final UserInvitationLookupGateway queryGateway;
  private final InvitationAcceptGateway acceptGateway;
  private final UserInvitationSessionGateway sessionGateway;
  private final TenantQueryRepositoryGateway tenants;

  /**
   * The open invitation of a link, to show its acceptance form.
   *
   * @param tenantName tenant of the request
   * @param rawToken token of the link
   * @return the invitation
   * @throws IllegalArgumentException when the link is unknown, used, cancelled or expired
   */
  public InvitationRecord open(String tenantName, String rawToken) {
    String tenantUid = tenantUid(tenantName);
    if (rawToken == null || rawToken.isBlank()) {
      throw new IllegalArgumentException(INVALID);
    }
    return queryGateway.findByToken(rawToken, tenantUid)
        .filter(invitation -> invitation.open(Instant.now()))
        .orElseThrow(() -> new IllegalArgumentException(INVALID));
  }

  public InvitationAcceptResult accept(InvitationAcceptParams params) {
    String password = params.getPassword();
    if (password == null || password.length() < MIN_PASSWORD) {
      throw new IllegalArgumentException(
          "The password must have at least " + MIN_PASSWORD + " characters.");
    }
    InvitationRecord invitation = open(params.getTenantName(), params.getRawToken());
    String userUid = acceptGateway.acceptAndCreateUser(invitation.uid(), password)
        .orElseThrow(() -> new IllegalArgumentException(INVALID));
    UserInvitationSession session = sessionGateway.createSession(userUid, invitation.email(),
        invitation.tenantUid(), params.getTenantName(), params.getClientId()).orElse(null);
    return new InvitationAcceptResult(invitation.email(), session);
  }

  private String tenantUid(String tenantName) {
    return tenants.find(TenantFilter.builder().name(tenantName).build())
        .filter(tenant -> tenant.isEnabled()).map(tenant -> tenant.getUid())
        .orElseThrow(() -> new IllegalArgumentException(INVALID));
  }
}
